1	// Package indexroom implements chain ingestion with optional block
2	// timestamps, reorg handling, consistent paginated transaction queries, and
3	// time-bucketed transaction statistics over the main chain.
4	package indexroom
5	
6	import (
7		"fmt"
8		"sync"
9		"unicode/utf8"
10	)
11	
12	// Block is one ingested block with its transactions.
13	//
14	// Time is the optional block timestamp as non-negative Unix seconds. A nil
15	// pointer means the block carries no timestamp and is distinct from a
16	// timestamp of zero. Append and Reorg reject negative values; stored blocks
17	// keep their own copy, so mutating the pointer or its target after a call
18	// never affects the index. Block timestamps need not be monotonic: equal
19	// values and values that decrease with height are both accepted.
20	type Block struct {
21		Height int64
22		// Hash, Parent, and every Txs identifier must be valid UTF-8; Append and
23		// Reorg reject a block carrying invalid bytes rather than letting a
24		// snapshot export silently rewrite them to U+FFFD. Txs keeps empty and
25		// duplicated identifiers, order, case, and surrounding whitespace
26		// exactly as given.
27		Hash   string
28		Parent string
29		Txs    []string
30		Time   *int64
31	}
32	
33	// Index is the durable chain view.
34	//
35	// Append, Reorg, QueryTxs, QueryTimeStats, Export, and Restore are safe for
36	// concurrent use; the exported fields are meant for read-only inspection
37	// after all calls have finished.
38	type Index struct {
39		Blocks map[int64]Block
40		ByHash map[string]int64
41		Tip    int64
42	
43		mu  sync.Mutex
44		key [32]byte
45	}
46	
47	// New returns an empty index.
48	func New() *Index {
49		return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}, key: newKey()}
50	}
51	
52	// reorgAppliedHookLocked is a test-only rendezvous invoked from Reorg once
53	// the alternate branch has fully replaced the old tip range, while index.mu
54	// is still held and before the call returns. It is nil in production; reorg
55	// regression tests park a successful reorg here with the new chain already in
56	// effect, so a QueryTimeStats issued at that instant is forced to wait and,
57	// once it runs, must observe the complete new chain.
58	var reorgAppliedHookLocked func(newTip int64)
59	
60	// Append accepts a block only when it extends the current tip, keeping the
61	// chain linear. Re-submitting a block identical to one already on the main
62	// chain is a successful no-op. A block whose hash, parent, or any transaction
63	// identifier carries invalid UTF-8 is rejected with an error naming the
64	// height and field (and the zero-based tx position); a rejected append leaves
65	// the index untouched.
66	func (index *Index) Append(block Block) error {
67		index.mu.Lock()
68		defer index.mu.Unlock()
69		return index.appendLocked(block)
70	}
71	
72	func (index *Index) appendLocked(block Block) error {
73		if err := validateBlockEncoding(block); err != nil {
74			return err
75		}
76		if block.Hash == "" {
77			return errInvalid("block needs a hash")
78		}
79		if block.Time != nil && *block.Time < 0 {
80			return errInvalid("block time must not be negative")
81		}
82		if index.Tip == 0 {
83			// Empty index: only the first block at height 1 is accepted; its
84			// parent becomes the chain start identifier and need not be indexed.
85			if block.Height != 1 {
86				return errInvalid("first block must be at height 1")
87			}
88			index.storeLocked(block)
89			return nil
90		}
91		if old, exists := index.Blocks[block.Height]; exists {
92			if sameBlock(old, block) {
93				return nil
94			}
95			return errInvalid("height already indexed with different content")
96		}
97		if block.Height != index.Tip+1 {
98			return errInvalid("block height must extend the current tip")
99		}
100		if block.Parent != index.Blocks[index.Tip].Hash {
101			return errInvalid("parent does not match the current tip")
102		}
103		if _, exists := index.ByHash[block.Hash]; exists {
104			return errInvalid("hash already indexed at another height")
105		}
106		index.storeLocked(block)
107		return nil
108	}
109	
110	// Reorg replaces the tip range with an alternate branch and reports the
111	// dropped old heights in ascending order. The branch is validated in full
112	// before anything is applied — including UTF-8 validity of every block's
113	// hash, parent, and transaction identifiers, even in the last block — so a
114	// rejected reorg leaves the index exactly as it was and reports no dropped
115	// heights. Heights whose old block is identical to the new one are not
116	// reported; re-submitting the branch already in effect returns an empty list.
117	func (index *Index) Reorg(blocks []Block) ([]int64, error) {
118		index.mu.Lock()
119		defer index.mu.Unlock()
120	
121		if len(blocks) == 0 {
122			return nil, errInvalid("empty branch")
123		}
124		// Every identifier must be valid UTF-8 before any lookup or mutation.
125		// The first block's parent need not be indexed, but it still has to be
126		// encodable, and an error in the last block must reject the whole branch.
127		for _, block := range blocks {
128			if err := validateBlockEncoding(block); err != nil {
129				return nil, err
130			}
131		}
132		ancestor, ok := index.ByHash[blocks[0].Parent]
133		if !ok {
134			return nil, errInvalid("branch parent is unknown")
135		}
136		if blocks[0].Height != ancestor+1 {
137			return nil, errInvalid("branch must start at the ancestor height plus one")
138		}
139		seen := make(map[string]bool, len(blocks))
140		for i, block := range blocks {
141			if block.Hash == "" {
142				return nil, errInvalid("block needs a hash")
143			}
144			if block.Time != nil && *block.Time < 0 {
145				return nil, errInvalid("block time must not be negative")
146			}
147			if seen[block.Hash] {
148				return nil, errInvalid("duplicate hash inside branch")
149			}
150			seen[block.Hash] = true
151			if height, exists := index.ByHash[block.Hash]; exists && height <= ancestor {
152				return nil, errInvalid("hash conflicts with a retained block")
153			}
154			if i > 0 {
155				prev := blocks[i-1]
156				if block.Height != prev.Height+1 {
157					return nil, errInvalid("branch heights must be consecutive")
158				}
159				if block.Parent != prev.Hash {
160					return nil, errInvalid("branch parent does not match the previous block")
161				}
162			}
163		}
164	
165		// Everything validated; compute the dropped heights before mutating.
166		newTip := blocks[len(blocks)-1].Height
167		dropped := []int64{}
168		for height := ancestor + 1; height <= index.Tip; height++ {
169			if height > newTip {
170				dropped = append(dropped, height)
171				continue
172			}
173			if !sameBlock(index.Blocks[height], blocks[height-blocks[0].Height]) {
174				dropped = append(dropped, height)
175			}
176		}
177		for height := ancestor + 1; height <= index.Tip; height++ {
178			delete(index.ByHash, index.Blocks[height].Hash)
179			delete(index.Blocks, height)
180		}
181		index.Tip = ancestor
182		for _, block := range blocks {
183			index.storeLocked(block)
184		}
185		if reorgAppliedHookLocked != nil {
186			reorgAppliedHookLocked(index.Tip)
187		}
188		return dropped, nil
189	}
190	
191	// storeLocked records a validated block, copying its transactions and
192	// timestamp so later caller-side mutation cannot alter the stored block.
193	func (index *Index) storeLocked(block Block) {
194		if block.Txs != nil {
195			txs := make([]string, len(block.Txs))
196			copy(txs, block.Txs)
197			block.Txs = txs
198		}
199		if block.Time != nil {
200			t := *block.Time
201			block.Time = &t
202		}
203		index.Blocks[block.Height] = block
204		index.ByHash[block.Hash] = block.Height
205		index.Tip = block.Height
206	}
207	
208	// validateBlockEncoding rejects a block whose hash, parent, or any
209	// transaction identifier contains invalid UTF-8 bytes. JSON snapshots can
210	// only carry valid UTF-8 — the encoder would silently rewrite bad bytes to
211	// U+FFFD, merging distinct identifiers after a restore — so such a block can
212	// never enter the index. The error names the block height and the field; a
213	// bad transaction identifier also names its zero-based position. A genuine
214	// U+FFFD is valid UTF-8 and is never rejected by this check.
215	func validateBlockEncoding(block Block) error {
216		if !utf8.ValidString(block.Hash) {
217			return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "hash"))
218		}
219		if !utf8.ValidString(block.Parent) {
220			return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "parent"))
221		}
222		for position, tx := range block.Txs {
223			if !utf8.ValidString(tx) {
224				return errInvalid(fmt.Sprintf("block at height %d: field %q element %d contains invalid UTF-8 bytes", block.Height, "txs", position))
225			}
226		}
227		return nil
228	}
229	
230	// sameBlock reports whether two blocks are identical: same height, hash,
231	// parent, transactions in order, and timestamp presence and value. An empty
232	// tx list equals a missing one, but a missing timestamp never equals zero.
233	func sameBlock(a, b Block) bool {
234		if a.Height != b.Height || a.Hash != b.Hash || a.Parent != b.Parent {
235			return false
236		}
237		if len(a.Txs) != len(b.Txs) {
238			return false
239		}
240		for i := range a.Txs {
241			if a.Txs[i] != b.Txs[i] {
242				return false
243			}
244		}
245		if (a.Time == nil) != (b.Time == nil) {
246			return false
247		}
248		return a.Time == nil || *a.Time == *b.Time
249	}
250	
251	type errInvalid string
252	
253	func (e errInvalid) Error() string { return string(e) }
254

