1	package indexroom
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// This file guards the reorg rule that a hash living inside the replaced
9	// suffix may be reused by the alternate branch — including at a DIFFERENT
10	// height than it used to occupy. TestReorgRemovedSuffixHashesMayReappear
11	// already covers reuse at the original height; here the reused hashes move,
12	// so every lookup that resolves a hash must follow its new position:
13	//
14	//   - the dropped-height report must come from comparing the block AT each
15	//     replaced height, not from checking whether a hash still exists, so a
16	//     height whose old hash reappears elsewhere is still reported;
17	//   - a later branch rooted at a moved hash must start at the height the
18	//     hash occupies NOW, not the one it occupied before the first reorg;
19	//   - the reuse budget is exactly the replaced suffix: a hash at or below
20	//     the retained ancestor, or the same hash twice inside one branch,
21	//     rejects the whole reorg with no dropped heights and no state change.
22	//
23	// Shared fixture — old main chain, tip 5:
24	//
25	//	h1@1 parent g   txs [r1]          } retained range
26	//	h2@2 parent h1  txs [r2]          } (ancestor for every branch below)
27	//	h3@3 parent h2  txs [oldA]        } old suffix, replaced by the
28	//	h4@4 parent h3  txs [oldB1,oldB2] } relocated-hash branch: h4 and h5
29	//	h5@5 parent h4  txs [oldC]        } swap heights, h3 disappears
30	//
31	// Relocated-hash branch rooted at the retained h2:
32	//
33	//	n3@3 parent h2  txs [newA]        // fresh hash
34	//	h5@4 parent n3  txs [newB]        // h5 moved 5 -> 4
35	//	h4@5 parent h5  txs [newC1,newC2] // h4 moved 4 -> 5
36	//
37	// Every height above the ancestor changes content, so the dropped report is
38	// [3 4 5] even though h4 and h5 remain indexed afterwards.
39	
40	func relocatedHashOldChain() []Block {
41		return []Block{
42			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"r1"}},
43			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"r2"}},
44			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"oldA"}},
45			{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"oldB1", "oldB2"}},
46			{Height: 5, Hash: "h5", Parent: "h4", Txs: []string{"oldC"}},
47		}
48	}
49	
50	func relocatedHashBranch() []Block {
51		return []Block{
52			{Height: 3, Hash: "n3", Parent: "h2", Txs: []string{"newA"}},
53			{Height: 4, Hash: "h5", Parent: "n3", Txs: []string{"newB"}},
54			{Height: 5, Hash: "h4", Parent: "h5", Txs: []string{"newC1", "newC2"}},
55		}
56	}
57	
58	func buildRelocatedHashOldChain(t *testing.T) *Index {
59		t.Helper()
60		index := New()
61		for _, block := range relocatedHashOldChain() {
62			if err := index.Append(block); err != nil {
63				t.Fatalf("setup append at height %d: %v", block.Height, err)
64			}
65		}
66		return index
67	}
68	
69	// relocatedHashHits derives the expected occurrence list from an explicit
70	// chain, independent of the Index under test.
71	func relocatedHashHits(chain []Block) []TxHit {
72		hits := []TxHit{}
73		for _, block := range chain {
74			for position, tx := range block.Txs {
75				hits = append(hits, TxHit{
76					Height:    block.Height,
77					BlockHash: block.Hash,
78					TxID:      tx,
79					Position:  position,
80				})
81			}
82		}
83		return hits
84	}
85	
86	func relocatedHashNewChain() []Block {
87		chain := append([]Block{}, relocatedHashOldChain()[:2]...)
88		return append(chain, relocatedHashBranch()...)
89	}
90	
91	// The swap itself: both reused hashes land at heights different from their
92	// old ones, the branch replaces everything above the retained ancestor, and
93	// the dropped report lists every changed old height exactly once.
94	func TestReorgRelocatedHashesSwapHeights(t *testing.T) {
95		index := buildRelocatedHashOldChain(t)
96	
97		dropped, err := index.Reorg(relocatedHashBranch())
98		if err != nil {
99			t.Fatalf("relocated-hash reorg refused: %v", err)
100		}
101		// h4 and h5 are still indexed after the reorg, but the blocks AT heights
102		// 4 and 5 changed, so both heights must be reported; the retained range
103		// (1..2) must not appear.
104		if want := []int64{3, 4, 5}; !reflect.DeepEqual(dropped, want) {
105			t.Fatalf("dropped=%v, want %v (a hash reappearing must not hide a changed height)", dropped, want)
106		}
107		if index.Tip != 5 {
108			t.Fatalf("tip=%d, want 5", index.Tip)
109		}
110	
111		// The retained range is untouched, block for block.
112		for _, retained := range relocatedHashOldChain()[:2] {
113			stored, ok := index.Blocks[retained.Height]
114			if !ok || !sameBlock(stored, retained) {
115				t.Fatalf("retained height %d changed: %+v", retained.Height, stored)
116			}
117			if index.ByHash[retained.Hash] != retained.Height {
118				t.Fatalf("retained hash %q resolved to %d, want %d",
119					retained.Hash, index.ByHash[retained.Hash], retained.Height)
120			}
121		}
122	
123		// The moved hashes resolve to their NEW heights; the dropped hash is gone.
124		if got := index.ByHash["h5"]; got != 4 {
125			t.Fatalf("h5 resolved to height %d, want its new height 4", got)
126		}
127		if got := index.ByHash["h4"]; got != 5 {
128			t.Fatalf("h4 resolved to height %d, want its new height 5", got)
129		}
130		if _, ok := index.ByHash["h3"]; ok {
131			t.Fatal("dropped hash h3 still indexed")
132		}
133		if block := index.Blocks[4]; block.Hash != "h5" || block.Parent != "n3" {
134			t.Fatalf("height 4 holds %+v, want the relocated h5 block", block)
135		}
136		if block := index.Blocks[5]; block.Hash != "h4" || block.Parent != "h5" {
137			t.Fatalf("height 5 holds %+v, want the relocated h4 block", block)
138		}
139	
140		// Queries see only the new chain: the replacement transactions at their
141		// new heights and positions, nothing from the old blocks — oldB1/oldB2
142		// (old h4) and oldC (old h5) must not ride along on the reused hashes.
143		page, err := index.QueryTxs(TxQuery{})
144		if err != nil {
145			t.Fatal(err)
146		}
147		wantHits := relocatedHashHits(relocatedHashNewChain())
148		if !reflect.DeepEqual(page.Hits, wantHits) {
149			t.Fatalf("hits after relocated-hash reorg=%v, want %v", page.Hits, wantHits)
150		}
151		if page.TotalMatches != int64(len(wantHits)) || page.MatchedBlocks != 5 || page.ToHeight != 5 {
152			t.Fatalf("stats=%d/%d/to%d, want %d/5/to5",
153				page.TotalMatches, page.MatchedBlocks, page.ToHeight, len(wantHits))
154		}
155		for _, stale := range []TxHit{
156			{Height: 4, BlockHash: "h4", TxID: "oldB1", Position: 0},
157			{Height: 4, BlockHash: "h4", TxID: "oldB2", Position: 1},
158			{Height: 5, BlockHash: "h5", TxID: "oldC", Position: 0},
159			{Height: 3, BlockHash: "h3", TxID: "oldA", Position: 0},
160		} {
161			for _, hit := range page.Hits {
162				if hit == stale {
163					t.Fatalf("stale occurrence %+v survived the reorg via a reused hash", stale)
164				}
165			}
166			if page, err := index.QueryTxs(TxQuery{TxIDs: []string{stale.TxID}}); err != nil {
167				t.Fatal(err)
168			} else if len(page.Hits) != 0 || page.TotalMatches != 0 {
169				t.Fatalf("removed transaction %q still queryable: %+v", stale.TxID, page)
170			}
171		}
172	}
173	
174	// After the swap, a follow-up branch rooted at a moved hash must be anchored
175	// at the hash's CURRENT height. h4 now sits at height 5, so a branch whose
176	// first block has parent h4 must start at height 6; the service must not
177	// demand height 5 (the old position), must not attach the branch anywhere
178	// else, and must keep everything at and below the parent.
179	func TestReorgBranchRootedAtRelocatedHash(t *testing.T) {
180		index := buildRelocatedHashOldChain(t)
181		if _, err := index.Reorg(relocatedHashBranch()); err != nil {
182			t.Fatalf("setup reorg refused: %v", err)
183		}
184	
185		continuation := []Block{
186			{Height: 6, Hash: "m6", Parent: "h4", Txs: []string{"post1"}},
187			{Height: 7, Hash: "m7", Parent: "m6", Txs: []string{"post2", "post3"}},
188		}
189		dropped, err := index.Reorg(continuation)
190		if err != nil {
191			t.Fatalf("branch rooted at the relocated h4 refused (parent must resolve at its new height 5): %v", err)
192		}
193		if len(dropped) != 0 {
194			t.Fatalf("dropped=%v, want empty: the branch only extends beyond the tip", dropped)
195		}
196		if index.Tip != 7 {
197			t.Fatalf("tip=%d, want 7", index.Tip)
198		}
199	
200		// The parent block is still exactly where the first reorg put it, with
201		// the first replacement's content, and every block at or below it — the
202		// retained range and the whole relocated branch — survived.
203		if block := index.Blocks[5]; block.Hash != "h4" ||
204			!reflect.DeepEqual(block.Txs, []string{"newC1", "newC2"}) {
205			t.Fatalf("relocated parent at height 5 changed: %+v", block)
206		}
207		if index.ByHash["h4"] != 5 || index.ByHash["h5"] != 4 || index.ByHash["n3"] != 3 {
208			t.Fatalf("relocated hashes moved again: %v", index.ByHash)
209		}
210		for _, kept := range relocatedHashNewChain() {
211			stored, ok := index.Blocks[kept.Height]
212			if !ok || !sameBlock(stored, kept) {
213				t.Fatalf("kept height %d lost or altered: %+v", kept.Height, stored)
214			}
215		}
216		if block := index.Blocks[6]; block.Hash != "m6" || block.Parent != "h4" {
217			t.Fatalf("height 6 holds %+v, want m6 parented on the relocated h4", block)
218		}
219	
220		// The follow-up branch's transactions appear after the relocated parent's
221		// own, ordered by height and in-block position.
222		page, err := index.QueryTxs(TxQuery{})
223		if err != nil {
224			t.Fatal(err)
225		}
226		fullChain := append(relocatedHashNewChain(), continuation...)
227		wantHits := relocatedHashHits(fullChain)
228		if !reflect.DeepEqual(page.Hits, wantHits) {
229			t.Fatalf("hits after follow-up branch=%v, want %v", page.Hits, wantHits)
230		}
231		if page.TotalMatches != int64(len(wantHits)) || page.MatchedBlocks != 7 || page.ToHeight != 7 {
232			t.Fatalf("stats=%d/%d/to%d, want %d/7/to7",
233				page.TotalMatches, page.MatchedBlocks, page.ToHeight, len(wantHits))
234		}
235	}
236	
237	// The reuse budget is exactly the replaced suffix. A branch that takes a
238	// hash from the retained range (the ancestor or below), or that uses one
239	// hash twice, is rejected in full — no dropped heights, and the chain, the
240	// old blocks, and the query results stay exactly as they were, even when
241	// the conflict sits in the branch's last block.
242	func TestReorgRelocatedHashReuseBoundaries(t *testing.T) {
243		cases := map[string][]Block{
244			// h2 IS the branch ancestor: retained, so off-limits for reuse.
245			"ancestor hash reused": {
246				{Height: 3, Hash: "n3", Parent: "h2", Txs: []string{"newA"}},
247				{Height: 4, Hash: "h2", Parent: "n3", Txs: []string{"newB"}},
248			},
249			// h1 sits below the ancestor: equally retained.
250			"below-ancestor hash reused": {
251				{Height: 3, Hash: "n3", Parent: "h2", Txs: []string{"newA"}},
252				{Height: 4, Hash: "h1", Parent: "n3", Txs: []string{"newB"}},
253			},
254			// A suffix hash may move, but only once per branch.
255			"same relocated hash twice in branch": {
256				{Height: 3, Hash: "h4", Parent: "h2", Txs: []string{"newA"}},
257				{Height: 4, Hash: "n4", Parent: "h4", Txs: []string{"newB"}},
258				{Height: 5, Hash: "h4", Parent: "n4", Txs: []string{"newC"}},
259			},
260			// Valid blocks first, retained-range hash in the LAST block: the
261			// whole branch must still be rejected and nothing may be applied.
262			"retained hash conflict at branch end": {
263				{Height: 3, Hash: "n3", Parent: "h2", Txs: []string{"newA"}},
264				{Height: 4, Hash: "n4", Parent: "n3", Txs: []string{"newB"}},
265				{Height: 5, Hash: "h1", Parent: "n4", Txs: []string{"newC"}},
266			},
267			// Same, but the late conflict is a duplicate inside the branch.
268			"duplicate hash at branch end": {
269				{Height: 3, Hash: "n3", Parent: "h2", Txs: []string{"newA"}},
270				{Height: 4, Hash: "n4", Parent: "n3", Txs: []string{"newB"}},
271				{Height: 5, Hash: "n3", Parent: "n4", Txs: []string{"newC"}},
272			},
273		}
274		oldChain := relocatedHashOldChain()
275		wantHits := relocatedHashHits(oldChain)
276		for name, branch := range cases {
277			t.Run(name, func(t *testing.T) {
278				index := buildRelocatedHashOldChain(t)
279				blocks, byHash, tip := snapshot(index)
280	
281				dropped, err := index.Reorg(branch)
282				if err == nil {
283					t.Fatal("expected reorg refusal")
284				}
285				if len(dropped) != 0 {
286					t.Fatalf("dropped=%v, want no reported heights on a rejected reorg", dropped)
287				}
288				requireUnchanged(t, index, blocks, byHash, tip)
289	
290				page, err := index.QueryTxs(TxQuery{})
291				if err != nil {
292					t.Fatal(err)
293				}
294				if !reflect.DeepEqual(page.Hits, wantHits) ||
295					page.TotalMatches != int64(len(wantHits)) || page.ToHeight != 5 {
296					t.Fatalf("query results changed after rejected reorg: %+v", page)
297				}
298			})
299		}
300	}
301

