681	// After the first page pinned its range, every continuation outcome is
682	// deterministic: a block inside the pinned range changed or the chain shrank
683	// below the pinned upper bound -> ErrQueryChanged with a fully zeroed result.
684	func TestQueryTxsContinuationAfterReorgIsChangedAndZeroed(t *testing.T) {
685		t.Run("suffix replaced under a pinned tip", func(t *testing.T) {
686			index := buildQueryOldChain(t)
687			first, err := index.QueryTxs(TxQuery{PageSize: 3})
688			if err != nil {
689				t.Fatal(err)
690			}
691			if first.NextCursor == "" || first.ToHeight != 5 || first.TotalMatches != 10 {
692				t.Fatalf("unexpected first page: %+v", first)
693			}
694			if _, err := index.Reorg(queryNewShortBranch()); err != nil {
695				t.Fatal(err)
696			}
697			page, err := index.QueryTxs(TxQuery{PageSize: 3, Cursor: first.NextCursor})
698			requireChangedZeroed(t, page, err)
699		})
700	
701		t.Run("chain shortened below an explicit to", func(t *testing.T) {
702			index := buildQueryOldChain(t)
703			first, err := index.QueryTxs(TxQuery{To: 5, PageSize: 3})
704			if err != nil {
705				t.Fatal(err)
706			}
707			if _, err := index.Reorg(queryNewShortBranch()); err != nil {
708				t.Fatal(err) // tip becomes 4, below the pinned to 5
709			}
710			page, err := index.QueryTxs(TxQuery{To: 5, PageSize: 3, Cursor: first.NextCursor})
711			requireChangedZeroed(t, page, err)
712		})
713	
714		t.Run("block replaced inside the pinned range with the tip intact", func(t *testing.T) {
715			index := buildQueryOldChain(t)
716			first, err := index.QueryTxs(TxQuery{To: 5, PageSize: 3})
717			if err != nil {
718				t.Fatal(err)
719			}
720			// Same length as the old suffix, different content starting at h3:
721			// the tip stays 5 but the pinned fingerprint must not match.
722			sameLength := []Block{
723				{Height: 3, Hash: "k3", Parent: "h2", Txs: []string{"k"}},
724				{Height: 4, Hash: "k4", Parent: "k3", Txs: []string{"k"}},
725				{Height: 5, Hash: "k5", Parent: "k4", Txs: []string{"k"}},
726			}
727			if _, err := index.Reorg(sameLength); err != nil {
728				t.Fatal(err)
729			}
730			if index.Tip != 5 {
731				t.Fatalf("setup: tip must stay 5, got %d", index.Tip)
732			}
733			page, err := index.QueryTxs(TxQuery{To: 5, PageSize: 3, Cursor: first.NextCursor})
734			requireChangedZeroed(t, page, err)
735	
736			// The index stays usable: a fresh first page describes the new chain.
737			fresh, err := index.QueryTxs(TxQuery{PageSize: 100})
738			if err != nil {
739				t.Fatal(err)
740			}
741			liveChain := append([]Block{}, queryRetainedBlocks()...)
742			liveChain = append(liveChain, sameLength...)
743			want := referenceTxPage(liveChain, 100, 0)
744			if !reflect.DeepEqual(viewOf(fresh), viewOf(want)) {
745				t.Fatalf("fresh page=%+v, want %+v", fresh, want)
746			}
747		})
