750	func requireChangedZeroed(t *testing.T, page TxPage, err error) {
751		t.Helper()
752		if !errors.Is(err, ErrQueryChanged) {
753			t.Fatalf("err=%v, want ErrQueryChanged (page=%+v)", err, page)
754		}
755		if errors.Is(err, ErrInvalidArgument) {
756			t.Fatalf("a committed reorg must not be reported as an argument error: %v", err)
757		}
758		if !reflect.DeepEqual(page, TxPage{}) {
759			t.Fatalf("changed continuation must return no records, cursor, or statistics; got %+v", page)
760		}
761	}
