815		if second.TotalMatches != first.TotalMatches ||
816			second.MatchedBlocks != first.MatchedBlocks ||
817			second.ToHeight != first.ToHeight {
818			t.Fatalf("continuation stats=%d/%d/%d differ from first page %d/%d/%d",
819				second.TotalMatches, second.MatchedBlocks, second.ToHeight,
