829		// Every cursor minted against the old chain is now dead, including the
830		// first one, and neither leaks records: both return fully zeroed pages.
831		for name, cursor := range map[string]string{"page one": cursorOne, "page two": second.NextCursor} {
832			page, err := index.QueryTxs(TxQuery{PageSize: 2, Cursor: cursor})
833			if !errors.Is(err, ErrQueryChanged) || !reflect.DeepEqual(page, TxPage{}) {
834				t.Fatalf("%s cursor after reorg: page=%+v err=%v, want zeroed ErrQueryChanged", name, page, err)
835			}
836		}
837		// A fresh first page starts over on the complete new chain.
838		fresh, err := index.QueryTxs(TxQuery{PageSize: 3})
839		if err != nil {
840			t.Fatal(err)
841		}
842		if !reflect.DeepEqual(viewOf(fresh), viewOf(referenceTxPage(queryNewChainBlocks(), 3, 0))) {
843			t.Fatalf("fresh page after reorg=%+v", fresh)
844		}
